package com.obysoft.faithOS.controller;
import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.service.MinistryService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/ministries") public class MinistryController{private final MinistryService service;public MinistryController(MinistryService service){this.service=service;}@GetMapping public List<MinistryResponse> all(){return service.all();}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR')") public ResponseEntity<MinistryResponse> create(@Valid @RequestBody MinistryRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR')") public MinistryResponse update(@PathVariable Long id,@Valid @RequestBody MinistryRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN','PASTOR')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
